#!/usr/bin/env python3
"""Emit one normalized JSON event per active LVM2 thin pool."""
import json
import os
import subprocess
import time
from decimal import Decimal, InvalidOperation

LVS_CANDIDATES = ("/usr/sbin/lvs", "/sbin/lvs", "/usr/bin/lvs")
LVS = next((path for path in LVS_CANDIDATES if os.path.isfile(path) and os.access(path, os.X_OK)), None)


def emit(status, **fields):
    event = {"collector_schema": 1, "collector_status": status, "event_epoch_s": int(time.time())}
    event.update(fields)
    print(json.dumps(event, separators=(",", ":"), sort_keys=True))


def text(row, *names):
    for name in names:
        value = row.get(name)
        if value is not None and str(value).strip() != "":
            return str(value).strip()
    return ""


def number(value):
    try:
        return float(Decimal(str(value).strip()))
    except (InvalidOperation, ValueError):
        return None


def whole_bytes(value):
    try:
        return int(Decimal(str(value).strip()))
    except (InvalidOperation, ValueError):
        return None


if LVS is None:
    emit("lvs_not_found")
    raise SystemExit(0)

command = [
    LVS, "--reportformat", "json", "--units", "b", "--nosuffix",
    "-o", "vg_name,lv_name,lv_attr,segtype,data_percent,metadata_percent,lv_size,vg_free,seg_monitor,whenfull",
    "--select", "segtype=thin-pool",
]
command_env = os.environ.copy()
command_env["LC_ALL"] = "C"
command_env.pop("LD_LIBRARY_PATH", None)
try:
    completed = subprocess.run(
        command,
        check=False,
        capture_output=True,
        text=True,
        timeout=30,
        env=command_env,
    )
except (OSError, subprocess.TimeoutExpired):
    emit("command_error")
    raise SystemExit(0)
if completed.returncode != 0:
    emit("command_error", lvs_returncode=completed.returncode)
    raise SystemExit(0)
try:
    payload = json.loads(completed.stdout)
except json.JSONDecodeError:
    emit("invalid_json")
    raise SystemExit(0)

rows = []
for report in payload.get("report", []):
    rows.extend(report.get("lv", []))
if not rows:
    emit("no_thin_pool")
    raise SystemExit(0)

for row in rows:
    vg_name = text(row, "vg_name")
    pool_name = text(row, "lv_name")
    data_percent = number(text(row, "data_percent"))
    metadata_percent = number(text(row, "metadata_percent"))
    data_size_bytes = whole_bytes(text(row, "lv_size"))
    vg_free_bytes = whole_bytes(text(row, "vg_free"))
    status = "ok" if vg_name and pool_name and data_percent is not None and metadata_percent is not None else "metric_unavailable"
    emit(
        status,
        vg_name=vg_name,
        pool_name=pool_name,
        lv_attr=text(row, "lv_attr"),
        seg_type=text(row, "segtype", "seg_type"),
        data_percent=data_percent,
        metadata_percent=metadata_percent,
        data_size_bytes=data_size_bytes,
        vg_free_bytes=vg_free_bytes,
        seg_monitor=text(row, "seg_monitor"),
        when_full=text(row, "whenfull", "lv_when_full", "when_full"),
    )
